/bin/bash -lc "python - <<'PY'
import zipfile, os
for zp in ['inputs/scogs_animals.zip','inputs/scogs_fungi.zip']:
    print('\\n',zp)
    with zipfile.ZipFile(zp) as z:
        lens=[]; nseq=[]; bad=[]; suff={}
        for name in z.namelist():
            suff[name.split('.')[-1]]=suff.get(name.split('.')[-1],0)+1
            if name.endswith('/') or not (name.endswith('.faa') or name.endswith('.faa.mafft')): continue
            data=z.read(name).decode(errors='replace').splitlines()
            seqs=[]; s=''
            for line in data:
                if line.startswith('>'):
                    if s: seqs.append(s); s=''
                elif line.strip(): s+=line.strip()
            if s: seqs.append(s)
            if len(set(map(len,seqs)))"'!=1: bad.append((name,len(seqs),list(map(len,seqs))[:6]))
            else: lens.append(len(seqs[0])); nseq.append(len(seqs))
        print('"'suffix counts',suff)
        print('valid-ish count',len(lens),'bad',len(bad),'nseq set',sorted(set(nseq))[:20],'lens minmax',min(lens),max(lens))
        print('first bad',bad[:3])
PY"

